function minimumSteps(s) {
  // Simulate: keep swapping a black ball that has a white ball right after it until none is left.
  const balls = s.split('');
  let steps = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i + 1 < balls.length; i++) {
      if (balls[i] === '1' && balls[i + 1] === '0') {
        balls[i] = '0';
        balls[i + 1] = '1';
        steps++;
        changed = true;
      }
    }
  }
  return steps;
}

