function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? pick(8000, 10000) : pick(1, 14);
  const black = rand();
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < black ? '1' : '0';
  return [s];
}
